import{_ as t,c as n,o as a,ag as e}from"./chunks/framework._xRlcm3f.js";const i="/siyuan-plugin-publisher/images/shots/notion-new-integration.webp",r="/siyuan-plugin-publisher/images/shots/notion-workspace.webp",s="/siyuan-plugin-publisher/images/shots/notion-token.webp",l="/siyuan-plugin-publisher/images/shots/notion-connection.webp",k=JSON.parse('{"title":"Notion API 配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/common-notion.md","filePath":"platforms/common-notion.md","lastUpdated":1790228279000}'),d={name:"platforms/common-notion.md"};function h(c,o,p,g,m,u){return a(),n("div",null,[...o[0]||(o[0]=[e('<h1 id="notion-api-配置指南" tabindex="-1">Notion API 配置指南 <a class="header-anchor" href="#notion-api-配置指南" aria-label="Permalink to &quot;Notion API 配置指南&quot;">​</a></h1><p>通过 <strong>Notion API Token</strong> 发布到 Notion 页面。</p><p>Notion 的授权分两步：<strong>建集成拿 Token</strong>，再把集成<strong>连接到你自己的页面</strong>。第二步最容易被忽略，漏了会出现「Token 正确但读不到任何页面」。</p><h2 id="一、新建集成" tabindex="-1">一、新建集成 <a class="header-anchor" href="#一、新建集成" aria-label="Permalink to &quot;一、新建集成&quot;">​</a></h2><p>打开 Notion 集成页：<a href="https://www.notion.so/my-integrations" target="_blank" rel="noreferrer">https://www.notion.so/my-integrations</a></p><p>点 <strong>New integration</strong>：</p><p><img src="'+i+'" alt="点 New integration" loading="lazy"></p><ol><li><strong>Associated workspace</strong>：选你要发布到的工作空间。</li><li><strong>Name</strong>：给集成起个名字，例如 <code>siyuan-publisher</code>。</li><li>点 <strong>Submit</strong> 提交。</li></ol><p><img src="'+r+'" alt="填写工作空间与名称后提交" loading="lazy"></p><h2 id="二、复制-token" tabindex="-1">二、复制 Token <a class="header-anchor" href="#二、复制-token" aria-label="Permalink to &quot;二、复制 Token&quot;">​</a></h2><p>进入集成详情页 → 左侧选 <strong>Secrets</strong> → 在 <strong>Internal Integration Secret</strong> 一行点 <strong>Show</strong>，复制该 Token。</p><p><img src="'+s+'" alt="在 Secrets 里复制 Internal Integration Secret" loading="lazy"></p><div class="tip custom-block"><p class="custom-block-title">Token 只显示一次</p><p>复制后请妥善保存。泄露的 Token 可以在同一页点 <strong>Refresh</strong> 重置，重置后旧 Token 立即失效。</p></div><h2 id="三、把集成连接到你的页面" tabindex="-1">三、把集成连接到你的页面 <a class="header-anchor" href="#三、把集成连接到你的页面" aria-label="Permalink to &quot;三、把集成连接到你的页面&quot;">​</a></h2><p>这一步决定插件能看到哪些页面。</p><p><img src="'+l+'" alt="在页面菜单里 Add connections" loading="lazy"></p><ol><li>打开你要发布到的<strong>父页面</strong>（根页面）。</li><li>点右上角的 <strong>⋯</strong> 菜单 → 找到 <strong>Connections</strong> → <strong>Add connections</strong>。</li><li>选择刚建的集成。</li></ol><div class="warning custom-block"><p class="custom-block-title">这一步非常重要</p><p>Notion 默认<strong>不给</strong>集成任何页面权限。不连接的话，插件拉取根页面列表会为空。</p></div><p>连接后，该页面及其<strong>子页面</strong>都对集成可见。</p><h2 id="四、配置" tabindex="-1">四、配置 <a class="header-anchor" href="#四、配置" aria-label="Permalink to &quot;四、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>平台首页</td><td>通常固定 <code>https://www.notion.so/</code>，保持默认</td></tr><tr><td>API 地址</td><td>通常固定 <code>https://api.notion.com/v1</code>，保持默认</td></tr><tr><td>Token</td><td>第二步复制的集成 Token</td></tr><tr><td>预览规则</td><td>固定 <code>/[postid]</code>，不可修改；查看链接为 <code>https://www.notion.so/&lt;postid&gt;</code></td></tr><tr><td>根页面</td><td>点「验证」后从下拉选择，文章作为它的子页面创建</td></tr><tr><td>图床</td><td>Notion 只有「不使用」与「PicGo」两项（无内置图床）。选「PicGo」时图片先传外部图床，再以外部 image 块嵌入页面</td></tr></tbody></table><h2 id="五、验证与发布" tabindex="-1">五、验证与发布 <a class="header-anchor" href="#五、验证与发布" aria-label="Permalink to &quot;五、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ 拉取根页面列表 → 选根页面 → 保存。</li><li>快速发布 → 选 Notion → 发布。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="为什么发布到-notion-之后图片不显示" tabindex="-1">为什么发布到 Notion 之后图片不显示 <a class="header-anchor" href="#为什么发布到-notion-之后图片不显示" aria-label="Permalink to &quot;为什么发布到 Notion 之后图片不显示&quot;">​</a></h3><p>两种原因：</p><ol><li><strong>没有配图床</strong>。Notion 没有提供图片上传 API，无法直接上传图片。需要把图片传到图床，再以外链形式存进页面——也就是说，Notion 平台要选「PicGo」图床。</li><li><strong>图片链接是 http</strong>。Notion 出于安全只接受 <strong>https</strong> 外链，http 地址会被直接忽略。请确认图床返回的是 https 地址。参考 <a href="https://developers.notion.com/docs/working-with-files-and-media" target="_blank" rel="noreferrer">Notion 官方说明</a>。</li></ol><h3 id="提示-token-无效-验证失败" tabindex="-1">提示 Token 无效 / 验证失败 <a class="header-anchor" href="#提示-token-无效-验证失败" aria-label="Permalink to &quot;提示 Token 无效 / 验证失败&quot;">​</a></h3><p>确认 Token 完整无误，且是同一个工作空间下创建的。</p><h3 id="根页面列表为空" tabindex="-1">根页面列表为空 <a class="header-anchor" href="#根页面列表为空" aria-label="Permalink to &quot;根页面列表为空&quot;">​</a></h3><p>集成还没连接到页面。按第三节在目标页面的 <strong>⋯ → Connections → Add connections</strong> 里添加你的集成。</p><h3 id="不能修改已发布页面的根页面" tabindex="-1">不能修改已发布页面的根页面 <a class="header-anchor" href="#不能修改已发布页面的根页面" aria-label="Permalink to &quot;不能修改已发布页面的根页面&quot;">​</a></h3><p>Notion 平台限制。先删除该文档的发布记录，再用新根页面重新发布。</p><h3 id="查看链接打开提示登录" tabindex="-1">查看链接打开提示登录 <a class="header-anchor" href="#查看链接打开提示登录" aria-label="Permalink to &quot;查看链接打开提示登录&quot;">​</a></h3><p>Notion 页面默认私有，需要 Notion 账号且有访问权限才能打开。发布成功且链接正确时，这属于正常现象。</p><h3 id="更新文章为什么要等更久" tabindex="-1">更新文章为什么要等更久 <a class="header-anchor" href="#更新文章为什么要等更久" aria-label="Permalink to &quot;更新文章为什么要等更久&quot;">​</a></h3><p>Notion 基于块结构而非整篇文档，更新采用「先删除再发布」的方式，因此比普通更新耗时更长。</p>',37)])])}const _=t(d,[["render",h]]);export{k as __pageData,_ as default};
